-- 007_question_bank: versioned four-type training question bank.
-- Legacy rows remain uncategorized/unversioned until their first explicit edit or review.

-- @step extend_question_identity
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question') = 19 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND ((COLUMN_NAME IN ('regulation_id', 'version_id', 'category_id', 'concept_id', 'current_version_id') AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'difficulty' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'rubric' AND DATA_TYPE = 'text' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('type', 'source') AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'score' AND COLUMN_TYPE = 'decimal(5,2)' AND IS_NULLABLE = 'NO' AND COLUMN_COMMENT = '题库建议分值；考试实际分值另存'))) = 10 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND ((INDEX_NAME = 'idx_question_category_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'category_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_category_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'status' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_category_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'type' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_category_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 4 AND COLUMN_NAME = 'difficulty' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_concept' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'concept_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_current_version' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'current_version_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL))) = 6 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND INDEX_NAME = 'idx_question_category_pool') = 4 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND INDEX_NAME = 'idx_question_concept') = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND INDEX_NAME = 'idx_question_current_version') = 1 THEN 1 ELSE 0 END AS complete;
ALTER TABLE `question` MODIFY COLUMN `regulation_id` BIGINT UNSIGNED NULL COMMENT '可选制度来源', MODIFY COLUMN `version_id` BIGINT UNSIGNED NULL COMMENT '兼容字段：可选制度版本来源', MODIFY COLUMN `type` VARCHAR(16) NOT NULL COMMENT 'single / multiple / judgment / image', MODIFY COLUMN `score` DECIMAL(5,2) NOT NULL COMMENT '题库建议分值；考试实际分值另存', MODIFY COLUMN `source` VARCHAR(16) NOT NULL COMMENT 'ai / manual / import', ADD COLUMN `category_id` BIGINT UNSIGNED NULL COMMENT '培训类别；旧题未知保持 NULL' AFTER `version_id`, ADD COLUMN `difficulty` VARCHAR(16) NULL COMMENT 'easy / medium / hard；旧题未知保持 NULL' AFTER `category_id`, ADD COLUMN `concept_id` BIGINT UNSIGNED NULL COMMENT '可选同考点组' AFTER `difficulty`, ADD COLUMN `current_version_id` BIGINT UNSIGNED NULL COMMENT '当前题目版本；旧题首次编辑/审核时捕获' AFTER `concept_id`, ADD COLUMN `rubric` TEXT NULL COMMENT '图片题评分参考；其他题为 NULL' AFTER `analysis`, ADD KEY `idx_question_category_pool` (`category_id`, `status`, `type`, `difficulty`), ADD KEY `idx_question_concept` (`concept_id`), ADD KEY `idx_question_current_version` (`current_version_id`);

-- @step create_question_concept
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_concept' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_concept') = 7 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_concept' AND ((COLUMN_NAME = 'id' AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('category_id', 'created_by') AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'type' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'name' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(128)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'created_at' AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED') OR (COLUMN_NAME = 'updated_at' AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED on update CURRENT_TIMESTAMP(3)'))) = 7 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_concept') = 4 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_concept' AND ((INDEX_NAME = 'PRIMARY' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'uk_question_concept_scope' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'category_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'uk_question_concept_scope' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'type' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'uk_question_concept_scope' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'name' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL))) = 4 THEN 1 ELSE 0 END AS complete;
CREATE TABLE IF NOT EXISTS `question_concept` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `category_id` BIGINT UNSIGNED NOT NULL COMMENT '培训类别', `type` VARCHAR(16) NOT NULL COMMENT 'single / multiple / judgment / image', `name` VARCHAR(128) NOT NULL COMMENT '考点名称', `created_by` BIGINT UNSIGNED NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `uk_question_concept_scope` (`category_id`, `type`, `name`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='题目考点组';

-- @step create_question_version
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_version' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_version') = 28 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_version' AND ((COLUMN_NAME = 'id' AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('question_id', 'created_by') AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('category_id', 'concept_id', 'regulation_id', 'regulation_version_id', 'approved_by', 'reviewed_by') AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('source_page_group', 'source_page_start', 'source_page_end') AND DATA_TYPE = 'int' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'revision' AND DATA_TYPE = 'int' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'difficulty' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('type', 'source') AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'status' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'pending') OR (COLUMN_NAME = 'stem' AND DATA_TYPE = 'text' AND COLUMN_TYPE = 'text' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('options', 'answer') AND DATA_TYPE = 'json' AND COLUMN_TYPE = 'json' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('analysis', 'rubric') AND DATA_TYPE = 'text' AND COLUMN_TYPE = 'text' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'score_cents' AND DATA_TYPE = 'int' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('approved_at', 'reviewed_at', 'legacy_captured_at') AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'review_reason' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(1000)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'created_at' AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED'))) = 28 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_version') = 8 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_version' AND ((INDEX_NAME = 'PRIMARY' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'uk_question_version_revision' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'question_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'uk_question_version_revision' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'revision' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_version_candidate' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'category_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_version_candidate' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'type' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_version_candidate' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'difficulty' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_version_candidate' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 4 AND COLUMN_NAME = 'status' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_version_regulation' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'regulation_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL))) = 8 THEN 1 ELSE 0 END AS complete;
CREATE TABLE IF NOT EXISTS `question_version` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `question_id` BIGINT UNSIGNED NOT NULL, `revision` INT UNSIGNED NOT NULL, `category_id` BIGINT UNSIGNED NULL, `difficulty` VARCHAR(16) NULL COMMENT 'easy / medium / hard；旧捕获版本可 NULL', `type` VARCHAR(16) NOT NULL COMMENT 'single / multiple / judgment / image', `stem` TEXT NOT NULL, `options` JSON NOT NULL, `answer` JSON NOT NULL, `analysis` TEXT NULL, `rubric` TEXT NULL, `score_cents` INT UNSIGNED NOT NULL COMMENT '题库建议分值，整数分；考试实际分值另存', `concept_id` BIGINT UNSIGNED NULL, `regulation_id` BIGINT UNSIGNED NULL, `regulation_version_id` BIGINT UNSIGNED NULL, `source_page_group` INT UNSIGNED NULL COMMENT '实际 PDF 页组下标；旧题未知保持 NULL', `source_page_start` INT UNSIGNED NULL COMMENT '实际来源起始页（1-based）', `source_page_end` INT UNSIGNED NULL COMMENT '实际来源结束页（1-based）', `source` VARCHAR(16) NOT NULL COMMENT 'ai / manual / import', `status` VARCHAR(16) NOT NULL DEFAULT 'pending' COMMENT 'pending / approved / rejected', `approved_by` BIGINT UNSIGNED NULL, `approved_at` DATETIME(3) NULL, `reviewed_by` BIGINT UNSIGNED NULL, `reviewed_at` DATETIME(3) NULL, `review_reason` VARCHAR(1000) NULL, `created_by` BIGINT UNSIGNED NOT NULL, `legacy_captured_at` DATETIME(3) NULL COMMENT '仅表示升级时捕获，不代表历史考试版本', `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `uk_question_version_revision` (`question_id`, `revision`), KEY `idx_question_version_candidate` (`category_id`, `type`, `difficulty`, `status`), KEY `idx_question_version_regulation` (`regulation_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='不可变题目内容版本及审核轨迹';
